function calculateFactorial(n) {
  if (n < 0) {
    throw new Error("Input must be a non-negative integer.");
  }

  if (n === 0 || n === 1) {
    return 1;
  }

  let result = 1;
  let i = 2;
  while (i <= n) {
    result *= i;
    i++;
  }

  if (typeof result !== 'number' || !Number.isInteger(result)) {
    throw new Error("Factorial calculation resulted in a non-integer.");
  }

  if (result === Infinity) {
    throw new Error("Factorial result exceeded maximum safe integer.");
  }

  return result;
}

