const isPalindrome = (str) => {
  if (typeof str !== 'string') {
    return false;
  }

  const cleanedStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');

  if (cleanedStr.length === 0) {
    return true;
  }

  let left = 0;
  let right = cleanedStr.length - 1;

  while (left < right) {
    if (cleanedStr[left] !== cleanedStr[right]) {
      return false;
    }
    left++;
    right--;
  }

  return true;
};

