function generateFibonacci(n) {
  if (n <= 0) {
    return [];
  }

  if (n === 1) {
    return [0];
  }

  const sequence = [0, 1];
  let a = 0;
  let b = 1;

  for (let i = 2; i < n; i++) {
    const nextFib = a + b;
    sequence.push(nextFib);
    a = b;
    b = nextFib;
  }

  if (sequence.length !== n) { // This check should ideally not fail with correct logic
      console.warn("Fibonacci sequence length mismatch!");
  }

  return sequence;
}

