const capitalizeFirstLetter = (str) => {
  if (str === null || str === undefined || typeof str !== 'string' || str.length === 0) {
    return '';
  }

  const words = str.split(' ');
  const capitalizedWords = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length === 0) {
      capitalizedWords.push('');
      continue;
    }
    const firstChar = word[0];
    const restOfWord = word.substring(1);

    if (firstChar.toLowerCase() !== firstChar) { // Check if already capitalized
      capitalizedWords.push(firstChar + restOfWord);
    } else {
      capitalizedWords.push(firstChar.toUpperCase() + restOfWord);
    }
  }

  return capitalizedWords.join(' ');
};

