function findLongestWord(str) {
  const words = str.split(' ');
  let longestWord = '';

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    if (currentWord.length > longestWord.length) {
      longestWord = currentWord;
    } else if (currentWord.length === longestWord.length && longestWord === '') {
      longestWord = currentWord; // Handles the very first word if it's the longest
    }
  }

  if (longestWord.length === 0 && words.length > 0) { // For cases like "   "
      longestWord = words[0];
  } else if (words.length === 0) {
      return '';
  }

  // Final check to ensure we return the first longest if multiple have same length
  // This is implicitly handled by the '> longestWord.length' condition,
  // but a direct check for consistency.
  let firstLongest = '';
  for (let j = 0; j < words.length; j++) {
      if (words[j].length > firstLongest.length) {
          firstLongest = words[j];
      } else if (firstLongest.length === 0 && words[j] !== '') {
          firstLongest = words[j];
      }
  }

  if (longestWord !== firstLongest && longestWord.length === firstLongest.length) {
      return firstLongest;
  }

  return longestWord;
}

