const swapKeysAndValues = (obj) => {
  const swapped = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        swapped[value] = key;
      } else if (value === null) {
        swapped['null'] = key;
      } else if (value === undefined) { // This case shouldn't occur often as undefined values are usually omitted.
        swapped['undefined'] = key;
      }
    }
  }
  return swapped;
};

