  if (typeof radius !== 'number' || radius === null) {
    return NaN; 
  }

  if (radius < 0) {
    return NaN; 
  }

  if (radius === 0) {
    return 0;
  }

  const area = Math.PI * radius * radius;

  if (area === Infinity || area === -Infinity) {
    return NaN;
  }

  return area;
};

