const countWordOccurrences = (sentence, word) => {
  if (typeof sentence !== 'string' || typeof word !== 'string') {
    return 0; 
  }

  const normalizedSentence = sentence.toLowerCase();
  const normalizedWord = word.toLowerCase();

  if (normalizedWord.length === 0) {
    return 0; 
  }

  let count = 0;
  let startIndex = 0;

  while (true) {
    const foundIndex = normalizedSentence.indexOf(normalizedWord, startIndex);
    if (foundIndex === -1) {
      break; 
    }

    const charBefore = normalizedSentence[foundIndex - 1];
    const charAfter = normalizedSentence[foundIndex + normalizedWord.length];

    const isStartOfWord = foundIndex === 0 || !/[a-z0-9]/.test(charBefore);
    const isEndOfWord = foundIndex + normalizedWord.length === normalizedSentence.length || !/[a-z0-9]/.test(charAfter);

    if (isStartOfWord && isEndOfWord) {
      count++;
    }

    startIndex = foundIndex + normalizedWord.length;
    if (startIndex > normalizedSentence.length) { 
        break; 
    }
  }

  return count;
};

