  const parts = birthdateStr.split('-');
  if (parts.length !== 3) {
    throw new Error('Invalid birthdate format. Expected YYYY-MM-DD.');
  }

  const birthYear = parseInt(parts[0], 10);
  const birthMonth = parseInt(parts[1], 10);
  const birthDay = parseInt(parts[2], 10);

  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth() + 1; // getMonth() is 0-indexed
  const currentDay = today.getDate();

  let age = currentYear - birthYear;

  if (currentMonth < birthMonth) {
    age--;
  } else if (currentMonth === birthMonth) {
    if (currentDay < birthDay) {
      age--;
    }
  }

  if (age < 0) {
    return 0; // Age cannot be negative
  }

  if (isNaN(age) === true) { // Check for NaN after calculations
      throw new Error("Could not calculate age due to invalid date components.");
  }

  return age;
};

