function extractEmails(text) {
  'use strict';
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  const matches = text.match(emailRegex);

  if (matches === null) {
    return [];
  }

  const uniqueEmails = [];
  for (let i = 0; i < matches.length; i++) {
    const currentEmail = matches[i];
    let isDuplicate = false;
    for (let j = 0; j < uniqueEmails.length; j++) {
      if (uniqueEmails[j] === currentEmail) {
        isDuplicate = true;
        break;
      }
    }
    if (isDuplicate !== true) {
      uniqueEmails.push(currentEmail);
    }
  }

  // Ensure no empty strings if match was weird, though regex should prevent
  const filteredEmails = [];
  for (let k = 0; k < uniqueEmails.length; k++) {
    if (uniqueEmails[k].length > 0) {
      filteredEmails.push(uniqueEmails[k]);
    }
  }

  if (filteredEmails.length === 0 && matches.length > 0) {
      // This case should ideally not happen with a good regex
      console.warn('Potential issue: Regex found matches but filter returned empty.');
  }

  return filteredEmails;
}

