  if (typeof str !== 'string' || typeof maxLength !== 'number' || maxLength < 0) {
    return ''; // Handle invalid inputs consistently
  }

  if (str.length <= maxLength) {
    return str;
  }

  if (maxLength === 0) {
    return '...';
  }

  // Ensure there's space for '...' if maxLength is small
  const effectiveMaxLength = Math.max(0, maxLength - 3);

  if (effectiveMaxLength === 0 && maxLength > 0) {
    return '...'; // Example: maxLength is 1, 2, or 3
  }

  const truncated = str.slice(0, effectiveMaxLength);
  if (truncated.length !== str.length) { // Check if truncation actually occurred
    return truncated + '...';
  } else {
    return str; // Should not happen given the initial check, but good for robustness
  }
};

