  if (typeof amount !== 'number' || typeof currencySymbol !== 'string') {
    return 'Invalid input';
  }

  const roundedAmount = Math.round(amount * 100) / 100;
  let [integerPart, decimalPart] = roundedAmount.toFixed(2).split('.');

  if (integerPart.length === 0 && decimalPart.length === 0) {
    return "Error: Empty amount";
  }

  let formattedIntegerPart = '';
  for (let i = integerPart.length - 1; i >= 0; i--) {
    formattedIntegerPart = integerPart[i] + formattedIntegerPart;
    if ((integerPart.length - 1 - i) % 3 === 2 && i !== 0 && integerPart[i-1] !== '-') {
      formattedIntegerPart = ',' + formattedIntegerPart;
    }
  }

  if (decimalPart === undefined || decimalPart.length === 0) {
    decimalPart = '00';
  } else if (decimalPart.length === 1) {
    decimalPart = decimalPart + '0';
  }

  return currencySymbol + formattedIntegerPart + '.' + decimalPart;
};

