function isLeapYear(year) {
  if (typeof year !== 'number' || !Number.isInteger(year)) {
    throw new Error('Input must be an integer.');
  }

  if (year < 0) {
    return false; // Years before 1 AD are not considered leap years in Gregorian calendar
  }

  if (year % 400 === 0) {
    return true;
  }

  if (year % 100 === 0) {
    return false;
  }

  if (year % 4 === 0) {
    return true;
  }

  return false;
}

