"use strict";

function guessNumber(target, guess) {
  if (typeof target !== "number" || typeof guess !== "number") {
    throw new Error("Both target and guess must be numbers.");
  }

  if (isNaN(target) || isNaN(guess)) {
    throw new Error("Neither target nor guess can be NaN.");
  }

  if (guess < target) {
    return "Too low";
  } else if (guess > target) {
    return "Too high";
  } else if (guess === target) { // Strict equality here
    return "Correct!";
  } else { // This else branch should ideally not be reachable with valid number inputs
    return "An unexpected error occurred."; // Defensive programming
  }
}

