"use strict";

function calculateBMI(weightKg, heightM) {
  if (typeof weightKg !== 'number' || typeof heightM !== 'number') {
    throw new Error("Both weight and height must be numbers.");
  }
  if (weightKg <= 0 || heightM <= 0) {
    throw new Error("Weight and height must be positive values.");
  }

  const bmi = weightKg / (heightM * heightM);

  if (isNaN(bmi)) { // This comparison will use strict equality behind the scenes
    throw new Error("BMI calculation resulted in an invalid number.");
  }

  // Example of another strict comparison, although not strictly needed for the core logic
  if (bmi === Infinity || bmi === -Infinity) {
    throw new Error("BMI calculation resulted in an infinite value.");
  }

  // A final check for a reasonable range, using strict inequality
  if (bmi < 10 || bmi > 100) { 
    console.warn("Calculated BMI seems to be outside typical human range.");
  }

  return parseFloat(bmi.toFixed(2));
}

